do $$
declare owner_id uuid:=gen_random_uuid();stranger uuid:=gen_random_uuid();product_id uuid;table_id bigint;o jsonb;order_id bigint;original jsonb;groups jsonb;r jsonb;retry jsonb;request_id uuid:=gen_random_uuid();count_before integer;blocked boolean;coupon_count integer;
begin
 insert into auth.users(id,email,raw_user_meta_data) values(owner_id,owner_id||'@example.invalid','{"role":"negocio","business_name":"Order tools QA"}'),(stranger,stranger||'@example.invalid','{}');
 insert into public.products(restaurant_id,name,price) values(owner_id,'Meal',25) returning id into product_id;
 insert into public.restaurant_tables(restaurant_id,name) values(owner_id,'QA') returning id into table_id;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 execute 'set local role authenticated';
 perform public.open_cash_shift(owner_id,0);
 o:=public.create_pos_table_order(owner_id,jsonb_build_array(jsonb_build_object('id',product_id,'qty',6)),null,'dine_in',table_id,'cash',null,'QA');order_id:=(o->>'id')::bigint;original:=o->'items';
 groups:=jsonb_build_array(jsonb_build_array(jsonb_build_object('id',product_id,'qty',2)),jsonb_build_array(jsonb_build_object('id',product_id,'qty',1)));
 r:=public.record_cash_operation_once(request_id,'split_order',jsonb_build_object('p_order_id',order_id,'p_groups',groups,'p_expected_items',original));
 retry:=public.record_cash_operation_once(request_id,'split_order',jsonb_build_object('p_order_id',order_id,'p_groups',groups,'p_expected_items',original));
 assert r=retry,'Retry duplicated split';assert (r->>'account_count')::int=3,'Wrong account count';
 execute 'reset role';
 assert (select sum(total)=150 from public.orders where restaurant_id=owner_id),'Split lost value';
 assert (select sum((i->>'qty')::int)=6 from public.orders o cross join lateral jsonb_array_elements(o.items) i where o.restaurant_id=owner_id),'Split lost products';
 assert (select count(*)=3 from public.orders where restaurant_id=owner_id),'Split duplicated accounts';
 select items into original from public.orders where id=order_id;
 select count(*) into count_before from public.orders where restaurant_id=owner_id;
 execute 'set local role authenticated';
 blocked:=false;
 begin perform public.record_cash_operation_once(gen_random_uuid(),'split_order',jsonb_build_object('p_order_id',order_id,'p_groups',jsonb_build_array(jsonb_build_array(jsonb_build_object('id',product_id,'qty',1)),jsonb_build_array(jsonb_build_object('id',product_id,'qty',10))),'p_expected_items',original));exception when raise_exception then blocked:=true;end;
 assert blocked,'Invalid split accepted';
 execute 'reset role';
 assert (select count(*)=count_before from public.orders where restaurant_id=owner_id),'Partial split committed on error';
 insert into public.coupons(restaurant_id,code,discount_type,discount_value) values(owner_id,'QA10','percent',10),(stranger,'OTHER','fixed',1);
 insert into public.coupons(restaurant_id,code,discount_type,discount_value,ends_at) values(owner_id,'OLD','fixed',1,now()-interval '1 hour');
 execute 'set local role authenticated';
 select count(*) into coupon_count from public.list_order_coupon_options(order_id);assert coupon_count=1,'Expired or foreign coupon offered';
 o:=public.apply_order_coupon(order_id,'QA10');assert (o->>'total')::numeric=67.5,'Wrong coupon discount';
 perform public.register_pos_payment_v2(order_id,'cash',1,0,1);
 blocked:=false;begin perform public.apply_order_coupon(order_id,'QA10');exception when raise_exception then blocked:=true;end;assert blocked,'Coupon changed partially paid account';
 execute 'reset role';
 insert into public.coupons(restaurant_id,code,discount_type,discount_value) values(owner_id,'FULL','percent',100);
 execute 'set local role authenticated';
 o:=public.apply_order_coupon((r->'new_order_ids'->>0)::bigint,'FULL');
 assert (o->>'total')::numeric=0 and o->>'payment_status'='approved','Fully covered coupon left an unpayable account';
 perform set_config('request.jwt.claim.sub',stranger::text,true);
 blocked:=false;begin perform public.list_order_coupon_options(order_id);exception when raise_exception then blocked:=true;end;assert blocked,'Foreign cashier sees coupons';
 blocked:=false;begin perform public.record_cash_operation_once(gen_random_uuid(),'split_order',jsonb_build_object('p_order_id',order_id,'p_groups',groups,'p_expected_items',original));exception when raise_exception then blocked:=true;end;assert blocked,'Foreign cashier split order';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 blocked:=false;begin perform public.create_staff_invite('driver');exception when raise_exception then blocked:=true;end;assert blocked,'Driver invited while delivery disabled';
 execute 'reset role';
end;$$;
